def compute(vars):
    reporting_date_fair_value = vars["Fair Value on the Reporting Date"]
    previous_date_fair_value = vars["Fair Value on the Previous Reporting Date (or Initial Recognition Date)"]
    fair_value_change_gains_losses = reporting_date_fair_value - previous_date_fair_value

    return {
        "value": fair_value_change_gains_losses,
        "trace": {
            "Fair Value on the Reporting Date": reporting_date_fair_value,
            "Fair Value on the Previous Reporting Date (or Initial Recognition Date)": previous_date_fair_value,
            "Fair Value Change Gains/Losses": fair_value_change_gains_losses,
            "output_meta": {"currency": "CNY", "scale": "million", "unit": None}
        }
    }
